# 平台 A 堆模块里与「生成/测试数据」同级的机械降级：`/gen/`、`/resources/`、`/testEntities/`
# 不是产品行为（源码生成物/资源/测试夹具），只在 platform_rest 域生效（见 main 的 domain 判断）。
GENERATED_SEGMENTS = ("/gen/", "/resources/", "/testEntities/", "/testSource/", "/testData/")


def platform_family(path: str) -> str:
    """B12 的模块级兜底族：`platform/<模块>/...`。子族由 family_of 先按 PLATFORM_RULES 匹配。"""
    parts = path.split("/")
    return "module/" + (parts[1] if len(parts) > 1 else "(root)")


def platform_verdict(module: str) -> tuple:
    """模块级判词：A 堆 ⇒ `[ ]`（逐类判定待办）；B/C 堆 ⇒ `[-]`（附可移植性理由）。"""
    entry = MODULE_HEAP.get(module)
    if entry is None:
        return ("-", "B 堆（未单独点名的平台模块，按默认档）：没有 JVM 对象模型可移植；用到的行为在各域就地实现。")
    heap, reason = entry
    if heap == "A":
        return (" ", "A 堆（用户可见实现体）：" + reason + "；本批已把 A 堆子包按 PLATFORM_RULES 逐包拆完，未归族行只剩机械降级的生成物/测试源码。")
    return ("-", heap + " 堆：" + reason)


def family_of(path: str, platform_sub: bool = False) -> str:
    # B12（platform_rest）的行是**仓库根相对**的 `platform/<模块>/...`，所以按首段归模块族；
    # 其他四域（execution/xdebugger/projectviews/daemon）的枚举文件里**也有** `platform/...` 开头的行
    # （例如 `platform/lang-impl/src/com/intellij/execution/...`），它们必须继续走各自的 RULES ——
    # 否则会被吞进 `module/*` 兜底族，整域塌成 B12 的档位（2026-10-04 真踩过：xdebugger 全 635 类变 `[-]`）。
    if platform_sub and path.startswith("platform/"):
        for key, needles in PLATFORM_RULES:
            if any(needle in path for needle in needles):
                return key
        return platform_family(path)
    for key, needles in RULES:
        if any(needle in path for needle in needles):
            return key
    return "exec/misc"


def write_verdict_doc(payloads: list) -> str:
    """拼出判决书正文（族判词 + 计数 + 逐类表指针）。生成的东西不许手改。"""
    domains = [payload["domain"] for payload in payloads]
    title = " + ".join("`" + domain + "`" for domain in domains)
    lines = ["# 判决：" + title, "",
             "> 本文件由 `python scripts/verdict_table.py " + " ".join(domains) + "` **生成**，不要手改：",
             "> 族判词在脚本的 `FAMILIES` / `PLATFORM_FAMILIES` 表里（逐族读过源码给的），逐类表在 `docs/inventory/<域>_verdict_table.md`，",
             "> 门禁 `tests/verdict-generated.test.mjs` 读同名 `.json`。", ""]
    if domains == ["platform_rest"]:
        lines += ["方法（B12：A 堆逐模块 → 逐子族，B/C 堆逐模块判可移植性）：", "",
                  "1. **子族判词**：`platform/` 路径先按 `PLATFORM_RULES` 的路径片段归到 `lp/*`/`pf/*` 等子族，",
                  "   每个子族一条判词，写清用户可见行为在本仓落在哪个文件、缺什么；判词里引用的本仓路径由门禁逐个核对**真实存在**。",
                  "2. **模块兜底**：没有子族规则的包仍归 `module/<模块>` —— A 堆按 `[ ]` 写明「其余子包逐类判定待办」，",
                  "   B/C 堆按 `[-]` 写可移植性理由（A/B/C 分堆见 `MODULE_HEAP`）。",
                  "3. **机械修正**：上游测试源码（`testSources`/`tests/`）判 `[-]`；`gen/`/`resources/`/`testEntities/` 这类生成物与夹具判 `[-]`；",
                  "   子族判 `[~]` 而类本身是 Swing 组件本体的判 `[-]`（行为由本仓 DOM 落点承担）。",
                  "4. 机械信号由 `scripts/verdict_signals.py` 产出（行数 / Swing / 平台专属 / 在 TaoCode 里出现过没有），每行的档位都能复算。",
                  ""]
    else:
        lines += ["方法（与 B1–B7 同一口径，只是规模不同：本域 2243 类没法逐条手抄）：", "",
                  "1. **族级判词**：类按包归族（`RULES`），每族一条判词，写清用户可见行为在本仓落在哪个文件、缺什么；",
                  "   判词里引用的本仓路径由门禁逐个核对**真实存在**。",
                  "2. **逐类覆盖**：族档位落到族内每个类，再叠两类机械修正 ——",
                  "   ① `OVERRIDES` 的逐类例外（族整体一个档、个别类本仓真做了）；",
                  "   ② **Swing 降级**：族判 `[~]` 但类本身是 Swing 组件本体（`JComponent`/`paintComponent`/`JBPopup`/`JList`…）的判 `[-]`。",
                  "3. 机械信号由 `scripts/verdict_signals.py` 产出（行数 / Swing / 平台专属 / 在 TaoCode 里出现过没有），每行的档位都能复算。",
                  ""]
    total = {"x": 0, "~": 0, "blank": 0, "-": 0, "total": 0}
    for payload in payloads:
        counts = payload["counts"]
        lines += ["## " + payload["domain"] + "（" + str(counts["total"]) + " 类）", "",
                  "| 档 | 类数 |", "|---|---:|",
                  "| `[x]` | " + str(counts["x"]) + " |",
                  "| `[~]` | " + str(counts["~"]) + " |",
                  "| `[ ]` | " + str(counts["blank"]) + " |",
                  "| `[-]` | " + str(counts["-"]) + " |",
                  "| 合计 | " + str(counts["total"]) + " |", "",
                  "| 族 | 档 | 判词（本仓落点 / 缺什么） | 类数 |", "|---|---|---|---:|"]
        seen = {}
        for row in payload["rows"]:
            seen[row["family"]] = seen.get(row["family"], 0) + 1
        for family, count in sorted(seen.items(), key=lambda item: -item[1]):
            entry = payload["families"].get(family)
            if entry is None:      # 模块族（B12）：判词按模块名现算
                tier, reason = platform_verdict(family[len("module/"):])
            else:
                tier, reason = entry["tier"], entry["reason"]
            # 模块族（B12）里整族都被机械降级（testSource/gen/resources）时，族档必须跟着落表行，
            # 不能还印母族的 `[ ]` —— 表里会看起来像"这一族还没判"。
            if family.startswith("module/") and tier == " ":
                family_rows = [row for row in payload["rows"] if row["family"] == family]
                if family_rows and all(row["tier"] == "-" for row in family_rows):
                    tier = "-"
                    reason = "机械降级：本族落表行全部是上游测试源码/生成物（逐类理由见 `*_verdict_table.md` 的逐类表）。"
            lines.append("| `" + family + "` | `[" + tier + "]` | " + reason + " | " + str(count) + " |")
        lines.append("")
        for key in ("x", "~", "blank", "-", "total"):
            total[key] += counts[key]
    counts_line = ("`[x]` " + str(total["x"]) + " + `[~]` " + str(total["~"]) + " + `[ ]` " + str(total["blank"]) +
                   " + `[-]` " + str(total["-"]) + " = **" + str(total["total"]) + "**")
    lines += ["## 合计", "", counts_line,
              "（`execution` 1608 + `xdebugger` 635）" if domains != ["platform_rest"] else "（A/B/C 三堆按 §2；B12 本批把 A 堆拆成上表的子族，模块兜底里只剩机械降级的生成物/测试行）",
              ""]
    if domains == ["platform_rest"]:
        lines += ["**已知缺口（族判词里逐条写着，这里点名最要紧的几条）**：", "",
                  "- 本批把 `[ ]` 从 1115 收到 26：**新实现**了结构化搜索文本子集（`ss/matcher`/`ss/replace`/`ss/ui`）、大文件模式、Unwrap、分析忽略、包依赖、端点视图、Run Anything、音频提示（`src/audioCues.ts`/`src/audioCuePlayer.ts`/`src/audioCueHost.ts`，合成音替代上游 wav，各族判 `[~]`，落点分别在 `src/structuralSearch.ts`/`src/largeFileMode.ts`/`src/unwrap.ts`/`src/analysisIgnore.ts`/`src/packageDeps.ts`/`src/endpointIndex.ts`/`src/runAnything.ts` 加对话框/菜单/编辑器链路）；**逐包复核后发现早有落点**的族改判 `[~]`：外部工具、文件模板（内置 16 种，2026-10-05 实测 `native/workspace.cpp:998-1081` 的分支数，原写 17 是笔误）、`lp/exclude`、`lp/text-search`；其余 A 堆子包按平台专有性逐包判 `[-]`；",
                  "- 仍 `[ ]` 的只剩 2 族（判词里都写了缺的能力与排期）：`pf/trusted`（信任提示 + 受限模式，待项目打开流程/项目设置扩存储）、`lp/preview`（字面量图片/颜色内联预览）；",
                  "- `[-]` 的大头：PSI/索引/stub 层（`lp/indexing`/`lp/psi`/`ix*`/`an/dataflow`）、Swing/Compose 组件本体与 AWT 运行态（`pf/ide-impl`/`lp/swing-views`）、远程/遥测/JCEF/更新与下载通道、Facet/Module/EP 专有模型（`lp/framework`/`ic/facet`/`pf/project-generator`）；",
                  "- 模块级兜底不再是缺口：A 堆子包（`module/lang-impl`/`module/platform-impl`/`module/code-style-api`）已全部路由到上表子族或机械降级。", ""]
    else:
        lines += ["**已知缺口（族判词里逐条写着，这里点名最要紧的几条）**：", "",
                  "- 运行/调试本仓是「通用表单 + 实例模型 + DAP」：**没有** per-type 配置编辑器、模板与共享配置、多运行目标；",
                  "- 测试侧：断言视图（`src/assertionView.ts`）与结构化事件通道（`smRunner` 等价物，`src/testEventChannel.ts`，判 `[~]`）已落地；JUnit 检查规则做了纯文本子集（`src/junitInspections.ts`，判 `[~]`）；覆盖率做了报告侧子集（`src/coverageReport.ts` 读 JaCoCo/Kover XML，判 `[~]`），采集通道仍缺（见 `exec/coverage` 判词）；",
                  "- 调试侧本轮补上行内值（`src/debugInlineValues.ts` + 复用 `debugLineExtension` 的 `inlineValuesField`）、多行求值对话框与历史面板、监视持久化、断点的命中次数/日志入口与临时/依赖/静音/全清、最近附加目标、`ShowExecutionPoint`/`EvaluateInConsole`；仍缺逻辑断点组（断点写入口过 `src/App.vue`，本轮冻结）、悬停快速求值、附加进程列表（宿主无进程枚举通道）、Smart Step Into/强制单步（`src/bridge.ts` 冻结，Method union 里没有 `stepInTargets`）；",
                  "- `[-]` 的两大来源：JVM 内部管线（`ProcessHandler`/`ExecutionUtil`/`RunProfileStarter`）与 Swing 组件本体。", ""]
    return "\n".join(lines)


KNOWN_FLAGS = ("--check", "--dry-run", "--force", "--help", "-h")

HELP = """用法：python scripts/verdict_table.py [开关] <域…>（不给域 = execution xdebugger）

  默认（不给开关）  就地重写 docs/inventory/ 下的生成物 —— 与加开关之前逐字节一致。
  --dry-run        生成并与磁盘比对、打印差异，**一个字节都不写**。
  --check          生成并与磁盘比对，不一致就**非零退出**并列出差异（CI 用）。
  --force          越过「手写 §G 逐类表」护栏照常写盘（只对默认档有意义）。

判词真源是本脚本的 FAMILIES / PLATFORM_FAMILIES / MODULE_HEAP 表，生成物不许手改。
核对引擎：scripts/check_verdict_tables.py
退出码：0 一致／打印帮助；1 域名或护栏问题、`--check` 比出不一致；2 未知开关。
"""


def parse_flags(argv: list) -> tuple:
    """把 CLI 开关从域名里分出来。`--check` 比 `--dry-run` 严，两个都给按 `--check` 走。"""
    unknown = [arg for arg in argv if arg.startswith("-") and arg not in KNOWN_FLAGS]
    if unknown:
        print("未知开关：" + " ".join(unknown) + "\n" + HELP)
        return ("error", [])
    if "-h" in argv or "--help" in argv:
        return ("help", [])
    mode = "check" if "--check" in argv else ("dry-run" if "--dry-run" in argv else "write")
    return (mode, [arg for arg in argv if arg not in KNOWN_FLAGS])


def main() -> int:
    mode, domains = parse_flags(sys.argv[1:])
    if mode == "help":
        print(HELP)
        return 0
    if mode == "error":
        return 2
    domains = domains or ["execution", "xdebugger"]
    payloads = []
    artifacts = []       # (绝对路径, 生成内容)：三种档位算的是同一份，只有最后一步分岔
    guarded_docs = set()  # 判决书里有手写 §G ⇒ 默认档拒写（护栏）、比对档不核
    doc_notes = []       # 与加开关之前完全一致的「已写入」输出
    for domain in domains:
        listing = os.path.join(INV, domain + ".txt")
        signals = os.path.join(INV, domain + "_signals.json")
        if not os.path.isfile(listing) or not os.path.isfile(signals):
            print(f"{domain}: 缺 {listing} 或 {signals}")
            return 1
        # **就地重写护栏**（2026-10-06 事故）：本脚本只生成「族级判词」，而 `find-diff`/`actions` 两个域的
        # 判决书里还有一张**手写**的 `## G. 逐条总表`（630/317 行逐类判决 + 每行的上游 文件:行号 依据），
        # `tests/b7-verdict.test.mjs` / `tests/b6-verdict.test.mjs` 就是拿那张表当门禁用的。
        # 上一轮有人跑 `verdict_table.py find-diff` 把整篇正文盖掉了，门禁当场失配。
        # 所以：**目标判决书里只要还有 §G 逐类表，就连生成物一起拒绝写**（除非显式 `--force`）。
        # 要改那张表就去改判决文档本身；要改族判词就来改本脚本的 FAMILIES/PLATFORM_FAMILIES。
        verdict_doc = os.path.join(INV, "verdict-" + domain + ".md")
        if os.path.isfile(verdict_doc) and "## G. 逐条总表" in open(verdict_doc, encoding="utf-8").read():
            # 比对档根本不写盘，「覆盖手写 §G」的风险不成立 ⇒ 只把那份判决书从比对里摘出去，
            # 该域的 _verdict_table.json/.md 照常核；否则 CI 会因为「有人手写了 §G」而假红。
            if mode != "write":
                print("（" + mode + "）docs/inventory/verdict-" + domain
                      + ".md 有手写 §G 逐类表：判决书那条不参与比对，只核该域的 _verdict_table.json/.md")
                guarded_docs.add(verdict_doc)
            elif "--force" in sys.argv[1:]:
                print("（--force）覆盖含手写 §G 逐类表的 docs/inventory/verdict-" + domain + ".md —— 那张表的判决会全部丢失")
            else:
                print("拒绝生成 " + domain + "：docs/inventory/verdict-" + domain
                      + ".md 里有**手写的** `## G. 逐条总表`（逐类判决 + 上游依据），本脚本的族级生成物没有那张表，"
                        "覆盖 = 丢掉逐类判决并让 b* verdict 门禁变红。确实要重写就加 --force（并把 §G 从 git 里恢复回来）。")
                return 1
        rows = [line.strip() for line in open(listing, encoding="utf-8") if line.strip()]
        signal_rows = {row["path"]: row for row in json.load(open(signals, encoding="utf-8"))["rows"]}
        platform_sub = domain == "platform_rest"   # 只有 B12 域把 A 堆拆子族；其他域保持模块级口径
        families_all = dict(FAMILIES)
        if platform_sub:
            families_all.update(PLATFORM_FAMILIES)
        out = []
        for path in rows:
            name = re.sub(r"\.(java|kt)$", "", path.rsplit("/", 1)[-1])
            family = family_of(path, platform_sub=platform_sub)
            tier, reason = (platform_verdict(family[len("module/"):]) if family.startswith("module/") else families_all[family])
            override = next((value for needle, value in OVERRIDES.items() if needle in path), None)
            if override:
                tier, reason = override
            signal = signal_rows.get(path, {})
            # 机械降级①：**上游测试源码**里的类一律 `[-]` —— 本仓对标的是产品行为，
            # 不移植 IDEA 自己的测试（`testSources` / `tests/` 标记由 verdict_signals.py 判定）。
            if signal.get("test"):
                tier = "-"
                reason = "上游**测试源码**里的类（`testSources`/`tests/` 标记）：本仓对标的是产品行为，不移植 IDEA 自己的测试。"
            # 机械降级②（B12 域）：`/gen/`、`/resources/`、`/testEntities/` 是生成物、资源或测试夹具，不是产品行为。
            elif platform_sub and any(segment in path for segment in GENERATED_SEGMENTS):
                tier = "-"
                reason = "生成源码/资源/测试夹具（路径含 `gen/`/`resources/`/`testEntities/` 段）：不是产品行为，本仓对标产品特性，判 `[-]`。"
            # 机械降级③：族整体判 `[~]`（行为有落点），但**类本身是 Swing 组件本体**的那些不可移植 ——
            # 行为由本仓的 DOM 版本承担，组件类判 `[-]`（B1–B7 对 Swing 壳也是这个口径）。
            elif tier == "~" and signal.get("swing") and not signal.get("in_code"):
                tier = "-"
                reason = families_all[family][1] + " ／ 本类本身是 Swing 组件（机械信号命中），组件本体不可移植：行为由上面那个 DOM 落点承担。"
            presence = "真实代码" if signal.get("in_code") else ("只被注释引用" if signal.get("in_comment_only") else "从未出现")
            out.append({"name": name, "path": path, "family": family, "tier": tier, "reason": reason,
                        "lines": signal.get("lines", 0), "swing": bool(signal.get("swing")),
                        "platform": bool(signal.get("platform")), "test": bool(signal.get("test")), "presence": presence})
        counts = {"total": len(out)}
        for tier in ("x", "~", " ", "-"):
            counts[tier if tier != " " else "blank"] = sum(1 for row in out if row["tier"] == tier)
        payload = {"domain": domain, "counts": counts,
                   "families": {key: {"tier": value[0], "reason": value[1]} for key, value in families_all.items()},
                   "rows": out}
        for row in out:
            if row["family"].startswith("module/"):
                tier_value, reason_value = platform_verdict(row["family"][len("module/"):])
                payload["families"][row["family"]] = {"tier": tier_value, "reason": reason_value}
        artifacts.append((os.path.join(INV, domain + "_verdict_table.json"),
                          json.dumps(payload, ensure_ascii=False, indent=1)))
        # 逐类覆盖表（md）：门禁只读 json，md 给人看
        table_md = [f"# {domain} 逐类判决表（`scripts/verdict_table.py {domain}` 生成，勿手改）\n\n",
                    "| 档 | 类数 |\n|---|---:|\n"]
        for key, label in (("x", "[x]"), ("~", "[~]"), ("blank", "[ ]"), ("-", "[-]")):
            table_md.append(f"| {label} | {counts[key]} |\n")
        table_md.append(f"| 合计 | {counts['total']} |\n\n")
        table_md.append("| 类 | 族 | 档 | 行数 | Swing | 平台 | 测试 | TaoCode |\n|---|---|---|---:|---|---|---|---|\n")
        for row in out:
            table_md.append(f"| `{row['name']}` | {row['family']} | `[{row['tier']}]` | {row['lines']} | "
                            f"{'Y' if row['swing'] else ''} | {'Y' if row['platform'] else ''} | {'Y' if row['test'] else ''} | {row['presence']} |\n")
        artifacts.append((os.path.join(INV, domain + "_verdict_table.md"), "".join(table_md)))
        print(f"{domain}: total={counts['total']} [x]={counts['x']} [~]={counts['~']} [ ]={counts['blank']} [-]={counts['-']}")
        payloads.append(payload)
    # 逐域一份判决书；B8 那两个域再合成一份（B8 的定义就是"execution + xdebugger"）
    for payload in payloads:
        target = os.path.join(INV, "verdict-" + payload["domain"] + ".md")
        if target in guarded_docs:      # 手写 §G 的判决书不是生成物，比对档别拿它当生成物核
            continue
        artifacts.append((target, write_verdict_doc([payload])))
        doc_notes.append("判决书已写入 docs/inventory/verdict-" + payload["domain"] + ".md")
    if [payload["domain"] for payload in payloads] == ["execution", "xdebugger"]:
        artifacts.append((os.path.join(INV, "verdict-execution-debug.md"), write_verdict_doc(payloads)))
        doc_notes.append("B8 合并判决书已写入 docs/inventory/verdict-execution-debug.md")
    if mode == "write":
        # 默认档：写盘内容与顺序、「已写入」那几行输出都与加开关之前一致（写只是从计算里挪到了最后一步）
        verdict_check.write_all(artifacts)
        for note in doc_notes:
            print(note)
        return 0
    reports = verdict_check.compare(artifacts, REPO)
    print(verdict_check.render(reports, REPO, mode))
    return 1 if (mode == "check" and not verdict_check.is_clean(reports)) else 0


if __name__ == "__main__":
    sys.exit(main())
